// 1. Create Short URL
POST /api/v1/urls
Headers:
  Authorization: Bearer <token>
  Idempotency-Key: 7c9e6679-7425-40de-944b-e07fc1f90ae7
Request Body:
{
  "long_url": "https://engineering.example.com/distributed-systems/ch1",
  "custom_alias": "sys-ch1",
  "expires_at": "2031-09-30T00:00:00Z"
}
Response (201 Created):
{
  "short_code": "9xK2pQ1",
  "short_url": "https://god.ly/9xK2pQ1",
  "long_url": "https://engineering.example.com/distributed-systems/ch1",
  "expires_at": "2031-09-30T00:00:00Z"
}

// 2. Redirect Endpoint
GET /{shortCode}
Response (302 Found):
  Location: https://engineering.example.com/distributed-systems/ch1
  Cache-Control: private, max-age=0, no-cache

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY users (PostgreSQL / Relational) {
  [PK ] user_id                BIGINT
  [IDX] email                  VARCHAR(255)
        api_key_hash           CHAR(64)
        tier                   ENUM('FREE','PRO')
        created_at             TIMESTAMPTZ
}

ENTITY short_urls (DynamoDB / Sharded SQL) {
  [PK ] short_code             VARCHAR(10)
  [FK ] user_id                BIGINT
        long_url               TEXT
  [IDX] expires_at             TIMESTAMPTZ
        created_at             TIMESTAMPTZ
}

ENTITY click_events (ClickHouse (Columnar)) {
  [PK ] event_id               UUID
  [FK ] short_code             VARCHAR(10)
  [IDX] clicked_at             DATETIME64
        country_iso            CHAR(2)
        user_agent             TEXT
}

// Relationships: users --(1 : N (owns))--> short_urls --(1 : N (logs clicks))--> click_events
